typedef struct {
    char a[MAXL], b[MAXL];
} Pair;

static Pair edges[MAXN];
static char names[2 * MAXN][MAXL];
static int nNames = 0;

static int get_id(const char *s) {
    for (int i = 0; i < nNames; ++i) {
        if (strcmp(names[i], s) == 0) return i;
    }
    strcpy(names[nNames], s);
