int main(void) {
    int n, q;
    if (scanf("%d", &n) != 1) return 0;

    for (int i = 0; i < n; ++i) {
        scanf("%63s %63s", edges[i].a, edges[i].b);
        get_id(edges[i].a);
        get_id(edges[i].b);
    }

    scanf("%d", &q);
    Pair *queries = (Pair *)malloc(sizeof(Pair) * q);
    for (int i = 0; i < q; ++i) {
        scanf("%63s %63s", queries[i].a, queries[i].b);
        get_id(queries[i].a);
        get_id(queries[i].b);
    }

    int m = nNames;
    static unsigned char reach[MAXN][MAXN];
    static unsigned char eq[MAXN][MAXN];

    for (int i = 0; i < m; ++i) {
        reach[i][i] = 1;
        eq[i][i] = 1;
    }

    /* Build equality graph:
       If two crossings share the first street, then their second streets are equal strength.
       If two crossings share the second street, then their first streets are equal strength.
    */
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            int a1 = get_id(edges[i].a), b1 = get_id(edges[i].b);
            int a2 = get_id(edges[j].a), b2 = get_id(edges[j].b);

            if (strcmp(edges[i].a, edges[j].a) == 0) {
                eq[b1][b2] = eq[b2][b1] = 1;
            }
            if (strcmp(edges[i].b, edges[j].b) == 0) {
                eq[a1][a2] = eq[a2][a1] = 1;
            }
        }
    }

    /* Transitive closure for equality */
    for (int k = 0; k < m; ++k)
        for (int i = 0; i < m; ++i)
            if (eq[i][k])
                for (int j = 0; j < m; ++j)
                    if (eq[k][j]) eq[i][j] = 1;

    /* Direct stronger relation from each known crossing:
       first street stronger than second street
    */
    for (int i = 0; i < n; ++i) {
        int a = get_id(edges[i].a);
        int b = get_id(edges[i].b);
        for (int x = 0; x < m; ++x) if (eq[x][a]) {
            for (int y = 0; y < m; ++y) if (eq[b][y]) {
                reach[x][y] = 1;
            }
        }
    }

    /* Equality also implies mutual reachability */
    for (int i = 0; i < m; ++i)
        for (int j = 0; j < m; ++j)
            if (eq[i][j]) reach[i][j] = 1;

    /* Transitive closure for stronger/equal relation */
    for (int k = 0; k < m; ++k)
        for (int i = 0; i < m; ++i)
            if (reach[i][k])
                for (int j = 0; j < m; ++j)
                    if (reach[k][j]) reach[i][j] = 1;

    for (int i = 0; i < q; ++i) {
        int a = get_id(queries[i].a);
        int b = get_id(queries[i].b);
        if (reach[a][b]) printf("Yes\n");
        else printf("No\n");
    }

    free(queries);
    return 0;
}

