    # Build adjacency after all streets known
    for u, v in edges:
        adj[u].add(v)

    def reachable(src, dst, n):
        visited = set()
        queue = deque([src])
        while queue:
            node = queue.popleft()
            if node == dst:
                return True
            if node in visited:
                continue
            visited.add(node)
            for nb in adj[node]:
                if nb not in visited:
                    queue.append(nb)
        return False

    results = []
    for _ in range(Q):
        a, b = input_data[idx], input_data[idx+1]
        idx += 2
        if a not in streets or b not in streets:
            results.append('?')
