                return idx[name]
            i = len(parent)
            idx[name] = i
            parent.append(i)
            rank.append(0)
            return i

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1

        # Read known crossings: the two streets crossing there have equal strength.
        for _ in range(n):
            a = next(it)
            b = next(it)
            union(get_id(a), get_id(b))

        # Answer queries.
        for _ in range(m):
            a = next(it)
            b = next(it)
            if a in idx and b in idx and find(idx[a]) == find(idx[b]):
                out.append("YES")
            else:
