/*
The statement is essentially asking reachability in a directed graph of street-strength relations.

Interpretation:
- Each known crossing "A B" means street A is stronger than street B.
- Strength is transitive.
- Queries ask whether the crossing is valid, i.e. whether one street is stronger than the other
  (in the intended order of the query).

Since the exact original input format is not shown in full, we use the standard format:
n m
n lines: stronger weaker
m lines: query_stronger query_weaker

Output:
For each query, print "Yes" if the first street is stronger than the second, otherwise "No".

Street names are arbitrary strings.

This solution:
- compresses street names to integer ids
- builds adjacency list
- for each distinct query source, runs BFS/DFS once
- answers all queries from that source

This is efficient for sparse graphs and many repeated sources.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    if (!(cin >> n >> m)) return 0;

    unordered_map<string, int> id;
    vector<pair<int,int>> edges;
    auto getId = [&](const string& s) -> int {
        auto it = id.find(s);
        if (it != id.end()) return it->second;
        int nid = (int)id.size();
        id[s] = nid;
        return nid;
    };

    for (int i = 0; i < n; ++i) {
        string a, b;
        cin >> a >> b;
        int u = getId(a);
        int v = getId(b);
        edges.push_back({u, v});
    }

    vector<pair<int,int>> queries(m);
    for (int i = 0; i < m; ++i) {
        string a, b;
        cin >> a >> b;
        int u = getId(a);
        int v = getId(b);
        queries[i] = {u, v};
    }

    int N = (int)id.size();
    vector<vector<int>> g(N);
    for (auto [u, v] : edges) g[u].push_back(v);

    // Group queries by source
    unordered_map<int, vector<pair<int,int>>> bySource;
    for (int i = 0; i < m; ++i) {
        bySource[queries[i].first].push_back({queries[i].second, i});
    }

    vector<string> ans(m);

    vector<int> vis(N, 0);
    int timer = 1;

    for (auto &entry : bySource) {
        int src = entry.first;
        queue<int> q;
        q.push(src);
        vis[src] = timer;

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            for (int v : g[u]) {
                if (vis[v] != timer) {
                    vis[v] = timer;
                    q.push(v);
                }
            }
        }

        for (auto [target, idx] : entry.second) {
            ans[idx] = (vis[target] == timer ? "Yes" : "No");
        }
        ++timer;
        if (timer == INT_MAX) {
            fill(vis.begin(), vis.end(), 0);
            timer = 1;
        }
    }

    for (int i = 0; i < m; ++i) {
        cout << ans[i] << '\n';
    }

    return 0;
}

