public class Main {
    static final int MAX = 100005;
    static List<Integer>[] graph = new ArrayList[MAX];
    static int[] strength = new int[MAX];
    static int[] visited = new int[MAX];
    static int currentTime = 0;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Initialize graph
        for (int i = 0; i < MAX; i++) {
            graph[i] = new ArrayList<>();
        }

        int n = sc.nextInt();
        int m = sc.nextInt();
        int q = sc.nextInt();

        // Read crossings and build graph
        for (int i = 0; i < n; i++) {
            int a = sc.nextInt();
            int b = sc.nextInt();
            graph[a].add(b);
            graph[b].add(a);
        }

        // Read known strength relationships
        for (int i = 0; i < m; i++) {
            int s = sc.nextInt();
            int t = sc.nextInt();
            String rel = sc.next();
            if (rel.equals(">")) {
                strength[s] = Math.max(strength[s], strength[t] + 1);
            } else if (rel.equals("<")) {
                strength[t] = Math.max(strength[t], strength[s] + 1);
            } else {
                // Equal
                strength[s] = Math.max(strength[s], strength[t]);
                strength[t] = Math.max(strength[t], strength[s]);
            }
        }

        // Process queries
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < q; i++) {
            int x = sc.nextInt();
            int y = sc.nextInt();
            String rel = sc.next();

            if (rel.equals(">")) {
                if (strength[x] > strength[y]) {
                    sb.append("1\n");
                } else if (strength[x] < strength[y]) {
                    sb.append("0\n");
                } else {
                    // Need to check if there's a path determining strength
                    if (hasPath(x, y)) {
                        sb.append("0\n");
                    } else if (hasPath(y, x)) {
                        sb.append("1\n");
                    } else {
                        sb.append("?\n");
                    }
                }
            } else if (rel.equals("<")) {
                if (strength[x] < strength[y]) {
                    sb.append("1\n");
                } else if (strength[x] > strength[y]) {
                    sb.append("0\n");
                } else {
                    if (hasPath(x, y)) {
                        sb.append("1\n");
                    } else if (hasPath(y, x)) {
                        sb.append("0\n");
                    } else {
                        sb.append("?\n");
                    }
                }
            } else {
                // Equal
                if (strength[x] == strength[y]) {
                    sb.append("1\n");
                } else {
                    sb.append("0\n");
                }
            }
        }

        System.out.print(sb.toString());
        sc.close();
    }

    static boolean hasPath(int from, int to) {
        currentTime++;
        return dfs(from, to);
    }

    static boolean dfs(int node, int target) {
        if (node == target) return true;
        visited[node] = currentTime;

        for (int next : graph[node]) {
            if (visited[next] != currentTime) {
                if (dfs(next, target)) return true;
            }
        }
        return false;
    }
}

