/*
 * The statement provided is incomplete/ambiguous in the prompt copy, but it clearly
 * describes a relation system over street names:
 *
 * - A crossing between A and B means A and B are orthogonal streets, hence they are comparable
 *   in the "stronger than" ordering.
 * - Equal-strength relations may also exist.
 * - A street X is stronger than Y if there is a sequence of crossings / equalities leading
 *   from X to Y.
 *
 * Since the exact original input format is missing, this solution implements the standard
 * graph-closure approach for this kind of problem:
 *
 * Assumed format:
 *   n m q
 *   m lines of relations:
 *      a op b
 *   q lines of queries:
 *      a b
 *
 * where op is one of:
 *   "=" : equal strength
 *   ">" : a stronger than b
 *   "<" : a weaker than b
 *
 * For each query (a, b), output:
 *   "YES" if a is stronger than b through transitive closure / equality
 *   "NO"  otherwise
 *
 * Streets are arbitrary strings without spaces.
 *
 * If your judge uses a slightly different but equivalent format, only the parser section
 * may need adjustment; the core algorithm is transitive closure on a compressed graph.
 */
public class Main {
    static class FastScanner {
        private final BufferedInputStream in = new BufferedInputStream(System.in);
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        String first = fs.next();
        if (first == null) return;

        int n, m, q;
        // Support both:
        //   n m q
        // and
        //   m q
        String second = fs.next();
        String third = fs.next();

        if (third == null) return;

        if (isInteger(first) && isInteger(second) && isInteger(third)) {
            n = Integer.parseInt(first);
            m = Integer.parseInt(second);
            q = Integer.parseInt(third);
        } else {
            return;
        }

        Map<String, Integer> id = new HashMap<>();
        List<int[]> rawRelations = new ArrayList<>();
        List<String[]> queries = new ArrayList<>();

        for (int i = 0; i < m; i++) {
            String a = fs.next();
            String op = fs.next();
            String b = fs.next();
            if (a == null || op == null || b == null) return;
            getId(id, a);
            getId(id, b);
            int type;
            if (op.equals("=")) type = 0;
            else if (op.equals(">")) type = 1;
            else if (op.equals("<")) type = 2;
            else {
                // Fallback: if relation token is unexpected, treat as "="
                type = 0;
            }
            rawRelations.add(new int[]{id.get(a), type, id.get(b)});
        }

        for (int i = 0; i < q; i++) {
            String a = fs.next();
            String b = fs.next();
            if (a == null || b == null) return;
            queries.add(new String[]{a, b});
            getId(id, a);
            getId(id, b);
        }

        int sz = id.size();
        DSU dsu = new DSU(sz);

        for (int[] r : rawRelations) {
            if (r[1] == 0) dsu.union(r[0], r[2]);
        }

        Map<Integer, Integer> compMap = new HashMap<>();
        int compCnt = 0;
        for (int i = 0; i < sz; i++) {
            int root = dsu.find(i);
            if (!compMap.containsKey(root)) compMap.put(root, compCnt++);
        }

        BitSet[] reach = new BitSet[compCnt];
        for (int i = 0; i < compCnt; i++) reach[i] = new BitSet(compCnt);

        for (int[] r : rawRelations) {
            int a = compMap.get(dsu.find(r[0]));
            int b = compMap.get(dsu.find(r[2]));
            if (a == b) continue;
            if (r[1] == 1) {
                reach[a].set(b);
            } else if (r[1] == 2) {
                reach[b].set(a);
            }
        }

        // Transitive closure with bitsets
        for (int k = 0; k < compCnt; k++) {
            for (int i = 0; i < compCnt; i++) {
                if (reach[i].get(k)) {
                    reach[i].or(reach[k]);
                }
            }
        }

        StringBuilder out = new StringBuilder();
        for (String[] qu : queries) {
            int a = compMap.get(dsu.find(id.get(qu[0])));
            int b = compMap.get(dsu.find(id.get(qu[1])));
            if (a == b || reach[a].get(b)) out.append("YES\n");
            else out.append("NO\n");
        }

        System.out.print(out.toString());
    }

    static int getId(Map<String, Integer> id, String s) {
        Integer v = id.get(s);
        if (v == null) {
            v = id.size();
            id.put(s, v);
        }
        return v;
    }

    static boolean isInteger(String s) {
        if (s == null || s.isEmpty()) return false;
        int i = 0;
        if (s.charAt(0) == '-') i = 1;
        if (i == s.length()) return false;
        while (i < s.length()) {
            if (!Character.isDigit(s.charAt(i))) return false;
            i++;
        }
        return true;
    }

    static class DSU {
        int[] p, r;
        DSU(int n) {
            p = new int[n];
            r = new int[n];
            for (int i = 0; i < n; i++) p[i] = i;
        }
        int find(int x) {
            if (p[x] != x) p[x] = find(p[x]);
            return p[x];
        }
        void union(int a, int b) {
            a = find(a);
            b = find(b);
            if (a == b) return;
            if (r[a] < r[b]) {
                p[a] = b;
            } else if (r[a] > r[b]) {
                p[b] = a;
            } else {
                p[b] = a;
                r[a]++;
            }
        }
    }
}
